package uk.ac.ravensbourne.casevault.web;
import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import uk.ac.ravensbourne.casevault.security.UserPrincipal; import uk.ac.ravensbourne.casevault.service.*; import uk.ac.ravensbourne.casevault.storage.EvidenceStorageHealthProbe;
/** Auditor-only administration; content-case routes remain unavailable to this role. */
@Controller @RequestMapping("/admin") @PreAuthorize("hasRole('AUDITOR_ADMIN')") public class AdminController { private final AdminAccountService accounts; private final AdminAuditService audits; private final EvidenceStorageHealthProbe storageHealth; public AdminController(AdminAccountService a,AdminAuditService u,EvidenceStorageHealthProbe storageHealth){accounts=a;audits=u;this.storageHealth=storageHealth;} @GetMapping("/accounts") String accounts(Model m){m.addAttribute("accounts",accounts.accounts());return "admin-accounts";} @PostMapping("/accounts/{id}/disable") String disable(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID id,@RequestParam String reason){accounts.disable(p,id,reason);return "redirect:/admin/accounts";} @PostMapping("/accounts/{id}/enable") String enable(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID id,@RequestParam String reason){accounts.enable(p,id,reason);return "redirect:/admin/accounts";} @PostMapping("/accounts/{id}/revoke") String revoke(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID id,@RequestParam String reason){accounts.revoke(p,id,reason);return "redirect:/admin/accounts";} @PostMapping("/accounts/{id}/force-password-reset") String reset(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID id,@RequestParam String reason){accounts.forcePasswordReset(p,id,reason);return "redirect:/admin/accounts";} @GetMapping("/audit") String audit(@AuthenticationPrincipal UserPrincipal p,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String action,Model m){audits.viewed(p);m.addAttribute("events",audits.events(page,size,action));return "admin-audit";} @PostMapping("/audit/verify") String verify(@AuthenticationPrincipal UserPrincipal p,Model m){m.addAttribute("verification",audits.verify(p));return "admin-audit-verify";} @GetMapping("/health") String health(Model m){m.addAttribute("storageStatus",storageHealth.probe());return "admin-health";} }
